const api = new ManagementApi();
const $ = (selector, base = document) => base.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const fmt = value => typeof value === 'number' ? value.toLocaleString(getLocale()) : String(value ?? '—');
let textSequence = 0;
const textValues = new Map();
function textNode(value) { const key = String(++textSequence); textValues.set(key, String(value ?? '')); return `<span data-text-node="${key}"></span>`; }
function hydrateText(root) { root.querySelectorAll('[data-text-node]').forEach(node => { node.textContent = textValues.get(node.dataset.textNode) ?? ''; textValues.delete(node.dataset.textNode); node.removeAttribute('data-text-node'); }); }
const date = value => value ? new Date(expiryMillis(value)).toLocaleString(getLocale(), { hour12: false }) : '—';
const PAGE_SIZE = 15;
const titles = labels({ accounts: "账号", resources: "资源", cards: "兵装", equipment: "装备", collection: "收藏", settings: "服务设置" });
const currencyNames = labels({ freeGems: "免费石", paidGems: "付费石", gf: 'GF', friendPoints: "友情点", stamina: "当前体力" });
const growthNames = labels({ level: "等级", awakening: "觉醒", mainSkillLevel: "主技能", killAbilityLevel: "击杀能力", killZoneSkillLevel: "击杀领域技能", masteryLevel: "熟练度", breakthrough: "突破" });
const itemTypes = labels({ 6: "道具", 7: "装备材料", 11: "觉醒素材", 12: "强化素材", 14: "活动物品" });
const state = { page: 'accounts', catalog: null, accounts: [], data: null, uid: '', lease: null, drafts: new Map(), selections: new Map(), search: {}, pages: {}, modes: { cards: 'owned', equipment: 'owned', collection: 'backgrounds' }, loading: false, pending: null, noticeTimer: null, leaseWasExpired: false, responseGeneration: 0, authenticated: false, unreadCredentials: null, resumeRequested: false, expertPeriod: null, expertSelection: null, materialCategory: 'all' };

function notify(message, error = false) {
  const node = $('#notice');
  node.textContent = message;
  node.classList.toggle('error', error);
  node.hidden = false;
  clearTimeout(state.noticeTimer);
  state.noticeTimer = setTimeout(() => { node.hidden = true; }, error ? 13000 : 6500);
}

function hideCredentials() {
  $('#credentials-result').replaceChildren();
  if ($('#credentials-dialog').open) $('#credentials-dialog').close();
}

function nativeCredentials(action, payload = {}) {
  if (window.__BRSF_NATIVE_CREDENTIALS__ !== true) return null;
  try { return JSON.parse(window.prompt('BRSF_CREDENTIALS_V1', JSON.stringify({ action, ...payload })) || 'null'); }
  catch { return null; }
}

function dismissCredentials() {
  if (state.unreadCredentials) { state.unreadCredentials.password = ''; state.unreadCredentials.takeoverId = ''; }
  state.unreadCredentials = null;
  nativeCredentials('clear');
  hideCredentials();
}

function credentialRecord(value) {
  return value && typeof value.takeoverId === 'string' && typeof value.password === 'string' && /^[1-9][0-9]{0,19}$/.test(String(value.uid)) && /^[A-Za-z0-9]{16}$/.test(value.takeoverId) && /^[A-Za-z0-9]{8,12}$/.test(value.password)
    ? { uid: String(value.uid), takeoverId: value.takeoverId, password: value.password } : null;
}

function restoreCredentials() {
  if (!state.authenticated || !state.catalog) return;
  const restored = nativeCredentials('restore');
  const record = credentialRecord(restored?.ok ? restored.record : null) || state.unreadCredentials;
  if (record) showCredentials(record, record.uid);
}

function fallbackCopy(text) {
  const previous = document.activeElement;
  const buffer = document.createElement('textarea');
  buffer.className = 'clipboard-buffer'; buffer.value = text; buffer.readOnly = true;
  ($('#credentials-dialog').open ? $('#credentials-dialog') : document.body).append(buffer);
  try { buffer.focus(); buffer.select(); buffer.setSelectionRange(0, text.length); return document.execCommand?.('copy') === true; }
  catch { return false; }
  finally { buffer.value = ''; buffer.remove(); previous?.focus?.(); }
}

async function copyCredentials(field) {
  const record = state.unreadCredentials;
  if (!state.authenticated || !record || !['id', 'password', 'all'].includes(field)) return;
  const text = field === 'id' ? record.takeoverId : field === 'password' ? record.password : `ID: ${record.takeoverId}\nPASS: ${record.password}`;
  let copied = false;
  if (window.__BRSF_NATIVE_CREDENTIALS__ === true) {
    if (nativeCredentials('retain', record)?.ok) copied = nativeCredentials('copy', { field })?.ok === true;
  } else {
    try { if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); copied = true; } }
    catch { /* The selectable-field fallback remains available. */ }
    if (!copied) copied = fallbackCopy(text);
  }
  if (copied) notify(field === 'id' ? t("ID 已复制。") : field === 'password' ? t("密码已复制。") : t("引继资料已复制。"));
  else {
    const input = $(field === 'password' ? '#credential-value-password' : '#credential-value-id');
    input?.focus(); input?.select();
    notify(t("复制失败，请长按字段复制。"), true);
  }
}

function abandonReview() {
  if (state.pending) { state.pending.password = ''; state.pending = null; }
  $('#review-body').replaceChildren();
  if ($('#review-dialog').open) $('#review-dialog').close();
}

function showLogin() {
  abandonReview(); hideCredentials();
  api.csrfToken = '';
  state.authenticated = false;
  state.responseGeneration++;
  state.lease = null; state.data = null; state.uid = ''; state.catalog = null; state.rawCatalog = null; state.accounts = [];
  state.expertPeriod = null; state.expertSelection = null;
  state.drafts.clear(); state.selections.clear();
  $('#workspace').hidden = true; $('#login').hidden = false;
  $('#page-content').replaceChildren();
  $('#owner-key').value = '';
}

function handleError(error) {
  if (error.status === 401 || error.code === 'auth_required') {
    showLogin(); notify(t("登录已过期，请重新登录。"), true); return;
  }
  if (error.code === 'csrf_invalid') { state.resumeRequested = true; notify(t("登录状态已变化，请重试。"), true); return; }
  if (['maintenance_required', 'maintenance_owned'].includes(error.code)) { state.lease = null; state.leaseWasExpired = true; abandonReview(); renderAccountStrip(); }
  if (error.code === 'stale_revision') { abandonReview(); notify(t("存档已更新，请刷新后重新预览。"), true); return; }
  const explanations = {
    maintenance_busy: t("请先结束战斗、周回或远征。"),
    maintenance_owned: t("账号正在维护，请稍后重试。"),
    maintenance_required: t("请重新进入维护后预览。"),
    operation_conflict: t("请关闭预览后重新操作。"),
    operation_gone: t("账号已删除，请刷新列表。"),
    csrf_invalid: t("请重新登录后重试。"),
    capacity_exceeded: t("数量超出上限，请减少后重试。")
  };
  notify(explanations[error.code] || (error instanceof ApiError ? error.message : apiErrorMessage(error.code, error.status)), true);
}

async function run(task) {
  if (state.loading) return;
  state.loading = true; document.body.setAttribute('aria-busy', 'true');
  const buttons = [...document.querySelectorAll('button')].filter(button => !button.disabled && !button.dataset?.copyCredentials && button.id !== 'credentials-dismiss');
  buttons.forEach(button => { button.disabled = true; });
  try { await task(); } catch (error) { handleError(error); }
  finally { state.loading = false; document.body.removeAttribute('aria-busy'); buttons.forEach(button => { if (button.isConnected) button.disabled = false; }); renderAccountStrip(); updateDraftCount(); syncSettingsControls(); if (state.resumeRequested) { state.resumeRequested = false; void resumeManagement(); } }
}

function liveLease() { return !!state.lease && expiryMillis(state.lease.expiresAt) > Date.now(); }
function writeDisabled() { return !state.data || !liveLease() ? 'disabled' : ''; }
function busyText(busy = {}) { return [busy.quest && t("战斗中"), busy.loop && t("周回中"), busy.expedition && t("远征中")].filter(Boolean).join(' / ') || t("空闲"); }
function selectedSet(key) { if (!state.selections.has(key)) state.selections.set(key, new Set()); return state.selections.get(key); }
function clearSubmittedSelections(key, submitted) { const current = selectedSet(key); for (const id of submitted) current.delete(String(id)); }
function draft(key, fallback) { return state.drafts.has(key) ? state.drafts.get(key) : fallback; }
function putDraft(key, value, original) { if (String(value) === String(original)) state.drafts.delete(key); else state.drafts.set(key, value); updateDraftCount(); }
function clearSubmittedDrafts(submitted, originals) {
  for (const [key, value] of submitted) {
    // A missing key means the user returned to the old stored value while preview was in flight.
    if (!state.drafts.has(key)) state.drafts.set(key, originals.get(key));
    else if (state.drafts.get(key) === value) state.drafts.delete(key);
  }
}
function updateDraftCount() { const count = state.drafts.size; $('#draft-count').textContent = count ? t("{p0} 项未保存修改", {p0: count}) : t("没有未保存修改"); $('#draft-count').classList.toggle('dirty', count > 0); }
function names(category, id) { const row = (state.catalog?.[category] || []).find(item => String(definitionId(item, category)) === String(id)); return definitionName(row) || t("目录编号 {p0}", {p0: id}); }
function nameCell(name, meta, glyph) { return `<div class="name-cell"><span class="glyph" aria-hidden="true">${glyph}</span><div><div class="name">${textNode(name)}</div><div class="meta">${esc(meta)}</div></div></div>`; }
function localizeCatalog(catalog) {
  const localized = { ...catalog };
  const language = getLanguage();
  for (const category of ['cards', 'equipment']) localized[category] = (catalog[category] || []).map(row => {
    const id = String(definitionId(row, category));
    const entry = localDisplayNames[category][id];
    const originalName = row.originalName || definitionName(row);
    const mapped = entry?.nameJa === originalName && entry?.source === 'local-translation';
    const english = catalogLocales[category][id] || entry?.nameEn || originalName;
    return { ...row, originalName, name: mapped ? (language === 'zh' ? entry.nameZh : language === 'ja' ? entry.nameJa : english) : originalName,
      latinName: mapped ? english : '', aliases: mapped ? `${entry.nameZh} ${entry.nameJa} ${english}` : '', translationSource: mapped ? 'local-translation' : 'unmapped' };
  });
  localized.items = (catalog.items || []).map(row => {
    const key = materialKey(row), entry = materialDisplay.items[key], extra = catalogLocales.items[key];
    const originalName = row.originalName || definitionName(row);
    const mapped = entry && entry.type === row.type && entry.id === row.id && entry.nameJa === originalName && (entry.eventId ?? null) === (row.eventId ?? null);
    return { ...row, originalName, name: mapped ? (language === 'zh' ? entry.nameZh : language === 'ja' ? entry.nameJa : extra?.nameEn || originalName) : originalName,
      latinName: mapped ? extra?.nameEn || '' : '', aliases: mapped ? `${entry.nameZh} ${entry.nameJa} ${extra?.nameEn || ''}` : '', materialCategory: mapped ? entry.category : null,
      usage: mapped ? (language === 'zh' ? entry.usage : language === 'ja' ? extra?.usageJa : extra?.usageEn) || '' : '',
      eventNameZh: mapped ? entry.eventNameZh || '' : '', eventNameJa: mapped ? entry.eventNameJa || '' : '' };
  });
  return localized;
}

function materialKey(row) { return `${row.type}:${row.id}:${row.eventId ?? ''}`; }
function materialImageRoute(row) {
  if (!Number.isSafeInteger(row.id) || row.id <= 0) return null;
  if (row.type === 14) return Number.isSafeInteger(row.eventId) && row.eventId > 0 ? `/management/images/items/14/${row.id}/${row.eventId}.png` : null;
  return [6, 7, 11, 12].includes(row.type) && row.eventId == null ? `/management/images/items/${row.type}/${row.id}.png` : null;
}
function materialNameCell(row) {
  const route = materialImageRoute(row);
  const image = route ? `<img data-catalog-thumb src="${route}" width="64" height="64" loading="lazy" decoding="async" alt=""><span class="catalog-art-fallback" hidden>${t("暂无图标")}</span>` : `<span class="catalog-art-fallback">${t("暂无图标")}</span>`;
  const original = row.originalName && row.originalName !== definitionName(row) ? `<div class="original-name">${textNode(row.originalName)}</div>` : '';
  return `<div class="name-cell catalog-name-cell material-name-cell"><span class="catalog-art">${image}</span><div><div class="name">${textNode(definitionName(row))}</div>${row.usage ? `<div class="material-usage">${textNode(row.usage)}</div>` : ''}${original}<div class="meta">#${esc(row.id)}${row.eventId ? t(" · 活动 {p0}", {p0: esc(row.eventId)}) : ''}</div></div></div>`;
}
function materialCategoryFilter() {
  const rows = state.catalog.items;
  const choices = Object.entries(materialDisplay.categories).map(([key, label]) => ({ key, label: t(label), count: rows.filter(row => row.materialCategory === key).length })).filter(row => row.count);
  return `<label class="material-filter"><span>${t("分类")}</span><select id="material-category"><option value="all" ${state.materialCategory === 'all' ? 'selected' : ''}>${t("全部（{p1}）", {p1: rows.length})}</option>${choices.map(row => `<option value="${row.key}" ${state.materialCategory === row.key ? 'selected' : ''}>${row.label}（${row.count}）</option>`).join('')}</select></label>`;
}
function catalogNameCell(row, category, meta) {
  const id = Number(definitionId(row, category));
  const image = Number.isSafeInteger(id) && id > 0
    ? `<img data-catalog-thumb src="/management/images/${category}/${id}.png" width="64" height="64" loading="lazy" decoding="async" alt=""><span class="catalog-art-fallback" hidden>${t("暂无缩略图")}</span>`
    : `<span class="catalog-art-fallback">${t("暂无缩略图")}</span>`;
  const original = [row?.originalName === definitionName(row) ? '' : row?.originalName, row?.latinName].filter(Boolean).join(' · ');
  return `<div class="name-cell catalog-name-cell"><span class="catalog-art">${image}</span><div><div class="name">${textNode(definitionName(row) || t("装备定义不可用"))}</div>${original ? `<div class="original-name">${textNode(original)}</div>` : ''}<div class="meta">${textNode(meta)}</div></div></div>`;
}
function empty(message) { return `<div class="empty">${esc(message)}</div>`; }
function needAccount() { return `<section class="panel">${empty(t("请先在「账号」页选择一个存档。"))}</section>`; }
function numberInput(key, value, min, max, options = '') { return `<input type="number" inputmode="numeric" step="1" data-draft="${esc(key)}" data-original="${esc(value)}" value="${esc(draft(key, value))}" min="${esc(min)}" ${Number.isFinite(max) ? `max="${max}"` : ''} ${options}>`; }
function paginate(rows, key) {
  const totalPages = Math.max(1, Math.ceil(rows.length / PAGE_SIZE));
  state.pages[key] = Math.min(state.pages[key] || 1, totalPages);
  const page = state.pages[key];
  return { rows: rows.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), footer: `<div class="pagination"><span>${t("共 {p0} 项 · 第 {p1} / {p2} 页", {p0: rows.length, p1: page, p2: totalPages})}</span><div class="actions"><button data-pagination="${key}" data-offset="-1" ${page <= 1 ? 'disabled' : ''}>${t("上一页")}</button><button data-pagination="${key}" data-offset="1" ${page >= totalPages ? 'disabled' : ''}>${t("下一页")}</button></div></div>` };
}
function matches(row, key, extras = '') { return `${definitionName(row)} ${row?.originalName || ''} ${row?.latinName || ''} ${row?.aliases || ''} ${row?.id ?? row?.cardId ?? row?.equipId ?? ''} ${extras}`.toLocaleLowerCase().includes((state.search[key] || '').toLocaleLowerCase()); }
function searchInput(key, placeholder) { return `<input id="search-${key}" type="search" data-search="${key}" value="${esc(state.search[key] || '')}" placeholder="${placeholder}" aria-label="${placeholder}">`; }
function modeTabs(page, modes) { return `<div class="tabs">${Object.entries(modes).map(([key, label]) => `<button data-mode-page="${page}" data-mode="${key}" class="${state.modes[page] === key ? 'active' : ''}">${label}</button>`).join('')}</div>`; }

function renderAccountStrip() {
  const data = state.data;
  $('#selected-account').innerHTML = data ? `<p class="eyebrow">${t("当前选择")}</p><h3>${textNode(data.account.name)}</h3><dl><dt>UID</dt><dd>${esc(state.uid)}</dd><dt>${t("等级")}</dt><dd>Rank ${esc(data.account.rank)}</dd><dt>${t("维护")}</dt><dd><span class="status-dot ${liveLease() ? 'active' : ''}"></span>${liveLease() ? t("维护中") : state.leaseWasExpired ? t("已失效") : t("未进入")}</dd></dl>` : `<p class="eyebrow">${t("当前选择")}</p><p class="small muted">${t("尚未选择账号")}</p>`;
  hydrateText($('#selected-account'));
  const banner = $('#maintenance-banner');
  banner.hidden = state.page === 'settings';
  banner.className = `maintenance-banner${liveLease() ? ' held' : state.leaseWasExpired ? ' expired' : ''}`;
  if (!data) { banner.innerHTML = `<span>${t("选择账号后进入维护。")}</span>`; return; }
  const remaining = liveLease() ? Math.max(0, Math.ceil((expiryMillis(state.lease.expiresAt) - Date.now()) / 1000)) : 0;
  banner.innerHTML = liveLease()
    ? `<span><strong>${t("账号维护中 · {p0} 秒", {p0: remaining})}</strong>${t("　修改后请在游戏中重新登录。")}</span><div class="actions"><button data-action="renew" ${state.loading ? 'disabled' : ''}>${t("续期")}</button><button data-action="release" ${state.loading ? 'disabled' : ''}>${t("释放维护")}</button></div>`
    : `<span>${state.leaseWasExpired ? t("维护已到期，请重新进入。") : t("当前{p0}。进入维护会退出游戏登录。", {p0: esc(busyText(data.busy))})}</span><button data-action="begin" ${state.loading ? 'disabled' : ''}>${t("进入账号维护")}</button>`;
  document.querySelectorAll('[data-requires-lease]').forEach(button => { button.disabled = state.loading || !liveLease(); });
}

function render() {
  $('#page-title').textContent = titles[state.page];
  document.querySelectorAll('[data-page]').forEach(button => { button.classList.toggle('active', button.dataset.page === state.page); button.setAttribute('aria-current', button.dataset.page === state.page ? 'page' : 'false'); });
  $('#page-content').innerHTML = ({ accounts: renderAccounts, resources: renderResources, cards: renderCards, equipment: renderEquipment, collection: renderCollection, settings: renderSettings })[state.page]();
  hydrateText($('#page-content'));
  syncSelectHeaders();
  renderAccountStrip(); updateDraftCount();
}

function syncSelectHeaders() {
  document.querySelectorAll('[data-select-visible]').forEach(header => {
    const choices = [...document.querySelectorAll(`[data-selection="${header.dataset.selectVisible}"]:not(:disabled)`)];
    const checked = choices.filter(choice => choice.checked).length;
    header.checked = choices.length > 0 && checked === choices.length;
    header.indeterminate = checked > 0 && checked < choices.length;
    header.disabled = !choices.length;
  });
}

function renderAccounts() {
  const rows = state.accounts.filter(row => `${row.name} ${row.uid}`.toLowerCase().includes((state.search.accounts || '').toLowerCase()));
  const paged = paginate(rows, 'accounts');
  return `<section class="panel"><div class="panel-head"><div><h2>${t("本地账号")}</h2><p class="muted">${t("选择要管理的账号。")}</p></div><span class="pill">${t("{p0} 个账号", {p0: state.accounts.length})}</span></div><div class="toolbar">${searchInput('accounts', t("搜索昵称或 UID"))}<span class="spacer"></span><button data-action="backup">${t("下载整服备份")}</button></div>${rows.length ? `<div class="table-wrap"><table class="accounts-table"><thead><tr><th>${t("账号")}</th><th>${t("等级")}</th><th>${t("兵装 / 装备")}</th><th>${t("运行状态")}</th><th></th></tr></thead><tbody>${paged.rows.map(row => `<tr class="account-row ${String(row.uid) === state.uid ? 'selected' : ''}"><td class="account-identity"><button type="button" class="account-identity-button" data-account-identity="true" data-select-account="${esc(row.uid)}" aria-pressed="${String(row.uid) === state.uid}">${nameCell(row.name, `UID ${row.uid}`, '▤')}</button></td><td class="account-meta" data-label="${t("等级")}">Rank ${esc(row.rank)}</td><td class="account-meta" data-label="${t("兵装 / 装备")}">${fmt(row.cardCount)} / ${fmt(row.equipmentCount)}</td><td class="account-meta" data-label="${t("运行状态")}"><span class="pill">${esc(busyText(row.busy))}</span></td><td class="account-choose"><button type="button" class="account-select-button" data-select-account="${esc(row.uid)}" aria-pressed="${String(row.uid) === state.uid}">${String(row.uid) === state.uid ? t("已选择") : t("选择账号")}</button></td></tr>`).join('')}</tbody></table></div>${paged.footer}` : empty(t("没有匹配的账号。"))}</section>
  ${state.data ? `<section class="panel"><div class="panel-head"><div><h2>${textNode(state.data.account.name)}</h2><p class="muted">${t("UID {p1} · 创建于 {p2}", {p1: esc(state.uid), p2: date(state.data.account.createdAt)})}</p></div><button data-action="export">${t("导出此账号")}</button></div><div class="panel-body"><dl class="inline-stat"><div><dt>${t("等级")}</dt><dd>Rank ${esc(state.data.account.rank)}</dd></div><div><dt>${t("已拥有兵装")}</dt><dd>${fmt(state.data.cards.length)}</dd></div><div><dt>${t("有效装备")}</dt><dd>${fmt(state.data.equipment.length)}</dd></div><div><dt>${t("体力 / 自然上限")}</dt><dd>${fmt(state.data.resources.stamina)} / ${fmt(state.data.resources.staminaMax)}</dd></div></dl></div></section>` : ''}
  <div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>${t("新建账号")}</h2><p class="muted">${t("创建账号并设置引继资料。")}</p></div></div><form id="create-form" class="panel-body"><div class="field"><label for="create-name">${t("新账号昵称")}</label><input id="create-name" name="name" required maxlength="64" autocomplete="off" placeholder="${t("输入昵称")}"></div><div class="field field-spaced"><label for="create-password">${t("引继密码")}</label><div class="form-line"><input id="create-password" name="password" type="password" required pattern="[A-Za-z0-9]{8,12}" minlength="8" maxlength="12" autocomplete="new-password" placeholder="${t("8–12 位英文字母或数字")}"><button type="button" data-generate-password="create-password">${t("随机生成")}</button></div><span class="field-note">${t("可自行输入或随机生成。")}</span></div><div class="form-footer"><span class="muted"></span><button type="submit" class="primary">${t("创建账号")}</button></div></form></section>
  <section class="panel"><div class="panel-head"><div><h2>${t("重新发行引继资料")}</h2><p class="muted">${t("设置新的引继密码。")}</p></div></div><form id="credentials-form" class="panel-body"><div class="warning">${t("发行后请使用新的 ID / PASS 登录。")}</div><div class="field field-spaced"><label for="reset-password">${t("新引继密码")}</label><div class="form-line"><input id="reset-password" name="password" type="password" required pattern="[A-Za-z0-9]{8,12}" minlength="8" maxlength="12" autocomplete="new-password" placeholder="${t("8–12 位英文字母或数字")}"><button type="button" data-generate-password="reset-password">${t("随机生成")}</button></div></div><div class="form-footer"><span class="muted">${state.uid ? t("当前 UID {p0}", {p0: esc(state.uid)}) : t("请先选择账号")}</span><button type="submit" class="primary" data-requires-lease ${writeDisabled()}>${t("重新发行")}</button></div></form></section></div>
  <p class="hint">${t("账号 JSON 不支持恢复；SQLite 备份包含全部账号数据。")}</p>`;
}

function renderResources() {
  if (!state.data) return needAccount();
  const resources = state.data.resources;
  const limits = state.catalog.limits;
  const caps = { freeGems: limits.maxFreeGems, paidGems: limits.maxPaidGems, gf: limits.maxGf, friendPoints: limits.maxFriendPoints, stamina: limits.maxStamina };
  const rows = state.catalog.items.filter(row => (state.materialCategory === 'all' || row.materialCategory === state.materialCategory) && matches(row, 'items', `${materialDisplay.categories[row.materialCategory] || ''} ${row.usage || ''} ${row.eventNameZh || ''} ${row.eventNameJa || ''} ${itemTypes[row.type] || ''}`));
  const paged = paginate(rows, 'items');
  return `<section class="panel"><div class="panel-head"><div><h2>${t("钱包与体力")}</h2><p class="muted">${t("设置钱包余额与体力。")}</p></div><span class="pill">${t("自然体力上限 {p0}", {p0: fmt(resources.staminaMax)})}</span></div><div class="panel-body"><div class="form-grid">${Object.keys(currencyNames).map(key => `<div class="field"><label>${currencyNames[key]}</label>${numberInput(`wallet:${key}`, resources[key], 0, caps[key], `aria-label="${currencyNames[key]}"`)}<span class="field-note">${t("允许 0–{p2}", {p2: fmt(caps[key])})}</span></div>`).join('')}</div><div class="form-footer"><span class="muted">${t("只提交已修改的数值。")}</span><div class="actions"><button data-action="stamina-full">${t("填入自然上限")}</button><button data-action="wallet-preview" class="primary" data-requires-lease ${writeDisabled()}>${t("预览余额调整")}</button></div></div></div></section>
  <section class="panel"><div class="panel-head"><div><h2>${t("道具与材料")}</h2><p class="muted">${t("按名称查找并批量设置目标数量；普通装备在「装备」页添加。")}</p></div><button data-action="items-preview" class="primary" data-requires-lease ${writeDisabled()}>${t("预览材料调整")}</button></div><div class="toolbar">${searchInput('items', t("搜索中文、日文、用途或编号"))}${materialCategoryFilter()}<span class="muted small">${t("每次最多 {p6} 项", {p6: fmt(limits.maxItemsPerCommand)})}</span></div>${rows.length ? `<div class="table-wrap"><table class="items-table"><thead><tr><th>${t("道具 / 材料")}</th><th>${t("类别")}</th><th>${t("当前数量")}</th><th>${t("目标数量")}</th></tr></thead><tbody>${paged.rows.map(row => { const item = state.data.items.find(x => x.type === row.type && x.id === row.id && (x.eventId ?? null) === (row.eventId ?? null)); const qty = item?.qty || 0; return `<tr class="item-row"><td class="item-identity">${materialNameCell(row)}</td><td class="item-category" data-label="${t("类别")}"><span class="pill">${esc(t(materialDisplay.categories[row.materialCategory]) || itemTypes[row.type])}</span></td><td class="item-current" data-label="${t("当前数量")}">${fmt(qty)}</td><td class="item-target" data-label="${t("目标数量")}">${numberInput(`item:${row.type}:${row.id}:${row.eventId ?? ''}`, qty, 0, row.maxQty, t("aria-label=\"道具 {p0} 目标数量\"", {p0: row.id}))}</td></tr>`; }).join('')}</tbody></table></div>${paged.footer}` : empty(t("没有匹配的道具。"))}</section>`;
}

function renderCards() {
  if (!state.data) return needAccount();
  const owned = new Map(state.data.cards.map(card => [card.cardId, card]));
  const mode = state.modes.cards;
  const rows = state.catalog.cards.filter(row => (mode === 'catalog' || owned.has(row.id)) && matches(row, 'cards', t("稀有度{p0}", {p0: row.rarity})));
  const paged = paginate(rows, 'cards'); const selection = selectedSet(`cards:${mode}`);
  return `<section class="panel"><div class="panel-head"><div><h2>${t("兵装管理")}</h2><p class="muted">${t("添加或培养兵装。")}</p></div><span class="pill">${t("已拥有 {p0}", {p0: owned.size})}</span></div><div class="toolbar">${modeTabs('cards', { owned: t("已拥有"), catalog: t("添加兵装") })}${searchInput('cards', t("搜索中文、日文、英文或编号"))}<span class="spacer"></span>${mode === 'owned' ? `<button data-action="cards-max-all" data-requires-lease ${writeDisabled()}>${t("拉满全部已有")}</button><button data-action="cards-max" class="primary" data-requires-lease ${writeDisabled()}>${t("拉满选中 ({p2})", {p2: selection.size})}</button>` : `<button data-action="cards-ensure" class="primary" data-requires-lease ${writeDisabled()}>${t("添加选中 ({p1})", {p1: selection.size})}</button>`}</div>${rows.length ? `<div class="table-wrap"><table class="catalog-table cards-table"><thead><tr><th class="selection-heading"><label class="select-page"><input type="checkbox" data-select-visible="cards:${mode}" aria-label="${t("选择本页兵装")}"><span>${t("选择本页")}</span></label></th><th>${t("兵装")}</th><th>${t("稀有度")}</th><th>${t("持有 / 成长")}</th><th></th></tr></thead><tbody>${paged.rows.map(row => { const card = owned.get(row.id); return `<tr class="has-selection"><td class="selection-cell"><label class="row-select"><input type="checkbox" data-selection="cards:${mode}" value="${row.id}" ${selection.has(String(row.id)) ? 'checked' : ''} aria-label="${t("选择目录编号 {p3}", {p3: row.id})}"></label></td><td class="identity-cell">${catalogNameCell(row, 'cards', `#${row.id}`)}</td><td data-label="${t("稀有度")}">★${esc(row.rarity)}</td><td data-label="${t("成长")}">${card ? `<span class="pill teal">${t("已拥有")}</span>${t("　Lv.{p0} · 觉醒 {p1}", {p0: card.level, p1: card.awakening})}` : `<span class="muted">${t("未拥有")}</span>`}</td><td class="row-actions">${card && mode === 'owned' ? `<button data-card-edit="${row.id}" data-requires-lease ${writeDisabled()}>${t("成长目标")}</button>` : ''}</td></tr>`; }).join('')}</tbody></table></div>${paged.footer}` : empty(t("没有匹配的兵装。"))}</section>`;
}

function renderEquipment() {
  if (!state.data) return needAccount();
  const mode = state.modes.equipment;
  const rows = (mode === 'owned' ? state.data.equipment.map(item => ({ ...item, definition: state.catalog.equipment.find(row => row.id === item.equipId) })) : state.catalog.equipment.map(row => ({ ...row, definition: row }))).filter(row => matches(row.definition, 'equipment', mode === 'owned' ? row.id : ''));
  const paged = paginate(rows, 'equipment'); const selection = selectedSet('equipment:owned');
  return `<section class="panel"><div class="panel-head"><div><h2>${t("装备库存")}</h2><p class="muted">${t("每件装备独立管理；成长调整保留原有词条。")}</p></div><span class="pill">${state.data.equipment.length} / ${state.catalog.limits.maxEquipment}</span></div><div class="toolbar">${modeTabs('equipment', { owned: t("已拥有"), catalog: t("添加装备") })}${searchInput('equipment', t("搜索中文、日文、编号或实例"))}<span class="spacer"></span>${mode === 'owned' ? `<button data-action="equipment-lock" data-locked="true" data-requires-lease ${writeDisabled()}>${t("锁定选中")}</button><button data-action="equipment-lock" data-locked="false" data-requires-lease ${writeDisabled()}>${t("解锁选中")}</button><button data-action="equipment-max" class="primary" data-requires-lease ${writeDisabled()}>${t("拉满选中 ({p3})", {p3: selection.size})}</button><button data-action="equipment-max-all" data-requires-lease ${writeDisabled()}>${t("拉满全部已有")}</button>` : ''}</div>${rows.length ? `<div class="table-wrap"><table class="catalog-table equipment-table"><thead><tr>${mode === 'owned' ? `<th class="selection-heading"><label class="select-page"><input type="checkbox" data-select-visible="equipment:owned" aria-label="${t("选择本页装备")}"><span>${t("选择本页")}</span></label></th>` : ''}<th>${t("装备")}</th><th>${t("稀有度")}</th>${mode === 'owned' ? `<th>${t("成长")}</th><th>${t("锁定")}</th>` : `<th>${t("类别")}</th>`}<th></th></tr></thead><tbody>${paged.rows.map(row => `<tr class="${mode === 'owned' ? 'has-selection' : ''}">${mode === 'owned' ? `<td class="selection-cell"><label class="row-select"><input type="checkbox" data-selection="equipment:owned" value="${esc(row.id)}" ${selection.has(String(row.id)) ? 'checked' : ''} aria-label="${t("选择装备实例{p2}", {p2: esc(row.id)})}"></label></td>` : ''}<td class="identity-cell">${catalogNameCell(row.definition, 'equipment', mode === 'owned' ? t("实例 {p0} · 定义 #{p1}", {p0: row.id, p1: row.equipId}) : `#${row.id}`)}</td><td data-label="${t("稀有度")}">★${esc(row.definition?.rarity ?? '—')}</td>${mode === 'owned' ? `<td data-label="${t("成长")}">${t("Lv.{p0} · 突破 {p1}", {p0: row.level, p1: row.breakthrough})}</td><td data-label="${t("锁定")}">${row.locked ? t("已锁定") : t("未锁定")}</td>` : `<td data-label="${t("类别")}"><span class="pill">${t("装备类别 {p0}", {p0: esc(row.type)})}</span></td>`}<td class="row-actions">${mode === 'owned' ? `<button data-equipment-edit="${esc(row.id)}" data-requires-lease ${writeDisabled()}>${t("成长目标")}</button>` : `<button data-equipment-grant="${row.id}" data-requires-lease ${writeDisabled()}>${t("添加装备")}</button>`}</td></tr>`).join('')}</tbody></table></div>${paged.footer}` : empty(t("没有匹配的装备。"))}</section>`;
}

function renderCollection() {
  if (!state.data) return needAccount();
  const category = state.modes.collection;
  const skinOwned = new Set(state.data.collections.skins.map(row => `${row.cardId}:${row.skinId}`));
  const owned = new Set(category === 'backgrounds' ? state.data.collections.backgroundIds : category === 'titles' ? state.data.collections.titleIds : []);
  const cards = new Set(state.data.cards.map(row => row.cardId));
  const rows = state.catalog[category].filter(row => matches(row, 'collection', category === 'skins' ? names('cards', row.cardId) : ''));
  const paged = paginate(rows, 'collection'); const selection = selectedSet(`collection:${category}`);
  const has = row => category === 'skins' ? skinOwned.has(`${row.cardId}:${row.id}`) : owned.has(row.id);
  return `<section class="panel"><div class="panel-head"><div><h2>${t("授予收藏")}</h2><p class="muted">${t("授予背景、称号或皮肤；皮肤需先拥有对应兵装。")}</p></div></div><div class="toolbar">${modeTabs('collection', { backgrounds: t("背景"), titles: t("称号"), skins: t("皮肤") })}${searchInput('collection', t("搜索原名、兵装名或编号"))}<span class="spacer"></span><button data-action="collection-grant" class="primary" data-requires-lease ${writeDisabled()}>${t("授予选中 ({p3})", {p3: selection.size})}</button></div>${rows.length ? `<div class="table-wrap"><table><thead><tr><th><input type="checkbox" data-select-visible="collection:${category}" aria-label="${t("选择本页可授予收藏")}"></th><th>${t("收藏")}</th><th>${t("状态")}</th>${category === 'skins' ? `<th>${t("对应兵装")}</th>` : ''}</tr></thead><tbody>${paged.rows.map(row => `<tr><td><input type="checkbox" data-selection="collection:${category}" value="${row.id}" ${selection.has(String(row.id)) ? 'checked' : ''} ${has(row) || (category === 'skins' && !cards.has(row.cardId)) ? 'disabled' : ''} aria-label="${t("选择目录编号 {p4}", {p4: row.id})}"></td><td>${nameCell(row.name, `#${row.id}`, '▧')}</td><td><span class="pill ${has(row) ? 'teal' : ''}">${has(row) ? t("已拥有") : category === 'skins' && !cards.has(row.cardId) ? t("需先拥有母卡") : t("可授予")}</span></td>${category === 'skins' ? `<td>${textNode(names('cards', row.cardId))}</td>` : ''}</tr>`).join('')}</tbody></table></div>${paged.footer}` : empty(t("没有匹配的收藏。"))}</section>`;
}

function periodDisplayName(period) {
  if (getLanguage() === 'zh' || getLanguage() === 'ja') return period.name;
  return period.name.replace(/^高度精鋭戦/, t('高度精鋭戦')).replace(/第([0-9０-９]+)期/g, (_, number) => t('开放期 {p0}', {p0:number}));
}

function renderSettings() {
  const data = state.expertPeriod;
  const current = data?.periods.find(period => period.questTypeId === data.activeQuestTypeId);
  return `<section class="panel" data-global-settings><div class="panel-head"><div><p class="eyebrow">${t("服务设置")}</p><h2>${t("高度精鋭戦")}</h2><p class="muted">${t("对所有账号生效。切换后完全退出并重新启动游戏，各期进度保留。")}</p></div><span class="pill teal">${t("全局")}</span></div><div class="panel-body">${data ? `<div class="current-period"><small>${t("当前开放期")}</small><strong>${textNode(periodDisplayName(current))}</strong><span class="number">#${esc(data.activeQuestTypeId)}</span></div><div class="server-setting-form"><div class="field"><label for="expert-period-select">${t("切换开放期")}</label><select id="expert-period-select">${data.periods.map(period => `<option value="${esc(period.questTypeId)}" ${String(period.questTypeId) === state.expertSelection ? 'selected' : ''}>${esc(periodDisplayName(period))} · #${esc(period.questTypeId)}</option>`).join('')}</select></div>${data.hasActiveBattle ? `<p class="settings-blocked">${t("请先结束战斗或循环。")}</p>` : ''}<div class="settings-actions"><button data-action="expert-period-refresh">${t("刷新状态")}</button><button id="expert-period-apply" data-action="expert-period-apply" class="primary" ${state.loading || data.hasActiveBattle || state.expertSelection === String(data.activeQuestTypeId) ? 'disabled' : ''}>${t("应用")}</button></div></div>` : `<div class="empty">${t("尚未读取服务设置。")}<div class="actions"><button data-action="expert-period-refresh">${t("读取设置")}</button></div></div>`}</div></section>`;
}

function syncSettingsControls() {
  const button = $('#expert-period-apply');
  if (button) button.disabled = state.loading || !state.expertPeriod || state.expertPeriod.hasActiveBattle || state.expertSelection === String(state.expertPeriod.activeQuestTypeId);
}

function expertPeriodData(data) {
  if (!data || !Number.isInteger(data.revision) || data.revision < 0 || !Number.isInteger(data.activeQuestTypeId) || !Number.isInteger(data.defaultQuestTypeId) || typeof data.hasActiveBattle !== 'boolean' || !Array.isArray(data.periods) || !data.periods.length || data.periods.some(period => !Number.isInteger(period.questTypeId) || period.questTypeId <= 0 || typeof period.name !== 'string') || !data.periods.some(period => period.questTypeId === data.activeQuestTypeId)) throw new ApiError('invalid_response', t("无法读取服务设置，请重试。"));
  return data;
}

async function refreshExpertPeriod() {
  const data = expertPeriodData(await api.expertPeriod());
  state.expertPeriod = data;
  if (!data.periods.some(period => String(period.questTypeId) === state.expertSelection)) state.expertSelection = String(data.activeQuestTypeId);
  if (state.page === 'settings') render();
}

async function applyExpertPeriod() {
  const current = state.expertPeriod;
  const questTypeId = Number(state.expertSelection);
  if (!current || !current.periods.some(period => period.questTypeId === questTypeId)) throw new ApiError('invalid_request', t("请选择开放期。"));
  if (current.hasActiveBattle) { notify(t("请先结束战斗或循环。"), true); return; }
  if (questTypeId === current.activeQuestTypeId) return;
  let result;
  try { result = expertPeriodData(await api.setExpertPeriod({ expectedRevision: current.revision, questTypeId })); }
  catch (error) {
    if (error.code === 'stale_revision') { notify(t("设置已变化，请刷新后重试。"), true); return; }
    if (error.code === 'battle_active') { notify(t("请先结束战斗或循环。"), true); return; }
    throw error;
  }
  state.expertPeriod = result;
  if (state.expertSelection === String(questTypeId)) state.expertSelection = String(result.activeQuestTypeId);
  if (state.page === 'settings') render();
  notify(t("开放期已切换，请完全退出并重新启动游戏。"));
}

async function loadWorkbench() {
  const generation = state.responseGeneration;
  const [catalog, accounts, status] = await Promise.all([api.catalog(), api.accounts(), api.status()]);
  if (generation !== state.responseGeneration) return;
  state.rawCatalog = catalog; state.catalog = localizeCatalog(catalog); state.accounts = accounts.items;
  state.authenticated = true;
  state.serverSchema = status.schemaVersion ?? '—'; $('#server-status').textContent = t("本机服主 · schema {p0}", {p0: state.serverSchema});
  $('#login').hidden = true; $('#workspace').hidden = false;
  render();
  restoreCredentials();
}

async function resumeManagement() {
  if (state.loading) { state.resumeRequested = true; return; }
  await run(async () => {
    const previousToken = api.csrfToken;
    const session = await api.session();
    if (!session.authenticated) {
      state.authenticated = false; hideCredentials(); abandonReview(); state.leaseWasExpired = !!state.lease; state.lease = null;
      $('#workspace').hidden = true; $('#login').hidden = false; $('#owner-key').value = '';
      return;
    }
    state.authenticated = true;
    if (!state.catalog) { await loadWorkbench(); return; }
    if (previousToken && previousToken !== api.csrfToken) {
      state.leaseWasExpired = !!state.lease; state.lease = null; abandonReview();
    }
    $('#login').hidden = true; $('#workspace').hidden = false;
    renderAccountStrip(); restoreCredentials();
  });
}

async function refreshData({ preserveDrafts = true } = {}) {
  const uid = state.uid; const generation = state.responseGeneration;
  const [data, accounts] = await Promise.all([uid ? api.account(uid) : Promise.resolve(null), api.accounts()]);
  if (uid !== state.uid || generation !== state.responseGeneration) return;
  if (data) state.data = data;
  state.accounts = accounts.items;
  if (!preserveDrafts) { state.drafts.clear(); state.selections.clear(); }
  render();
}

async function selectAccount(uid) {
  if (uid === state.uid) return;
  if ((state.drafts.size || liveLease()) && !confirm(t("切换账号会丢弃当前草稿，并释放当前维护。继续切换？"))) return;
  const generation = ++state.responseGeneration;
  hideCredentials(); abandonReview();
  if (liveLease()) { try { await api.release(state.uid, state.lease.leaseId); } finally { state.lease = null; state.leaseWasExpired = false; renderAccountStrip(); } }
  const data = await api.account(uid);
  if (generation !== state.responseGeneration) return;
  state.uid = String(uid); state.data = data; state.lease = null; state.leaseWasExpired = false;
  state.drafts.clear(); state.selections.clear(); state.pages = {}; abandonReview(); render();
}

function requireLease() { if (!liveLease()) throw new ApiError('maintenance_required', t("请先进入账号维护。")); }
function numeric(value, min, max, label) { const number = Number(value); if (!String(value).trim() || !Number.isSafeInteger(number) || number < min || (Number.isFinite(max) && number > max)) throw new ApiError('invalid_request', t("{p0}必须是 {p1}–{p2} 范围内的整数。", {p0: label, p1: min, p2: fmt(max)})); return number; }
function selectedIds(key, numericIds = true) { const ids = [...selectedSet(key)]; if (!ids.length) throw new ApiError('invalid_request', t("请至少选择一项。")); if (ids.length > state.catalog.limits.maxItemsPerCommand) throw new ApiError('invalid_request', t("每次最多选择 {p0} 项。", {p0: state.catalog.limits.maxItemsPerCommand})); return numericIds ? ids.map(Number) : ids; }
// PREVIEW_DIFF_START — pure DTO presentation, also exercised by the focused unit check.
export function buildPreviewSections(changes, catalog) {
  const sectionNames = { 资源: 'resources', 物品: 'items', 兵装: 'cards', 装备: 'equipment', 收藏: 'collections' };
  const resourceLabels = { freeGems: t("免费石"), paidGems: t("付费石"), gf: 'GF', friendPoints: t("友情点"), stamina: t("当前体力"), staminaMax: t("自然体力上限") };
  const cardLabels = { level: t("等级"), exp: t("累计经验"), awakening: t("觉醒"), mainSkillLevel: t("主技能等级"), killAbilityLevel: t("击杀能力等级"), killZoneSkillLevel: t("击杀领域技能等级"), masteryLevel: t("熟练度"), masteryExp: t("熟练度累计经验"), skinId: t("使用皮肤"), homeSkinId: t("主页皮肤"), profileSkinId: t("资料皮肤") };
  const equipLabels = { level: t("等级"), exp: t("累计经验"), breakthrough: t("突破"), locked: t("锁定"), properties: t("词条编号") };
  const typeLabels = { 6: t("道具 / 召唤券"), 7: t("装备材料"), 11: t("觉醒素材"), 12: t("强化素材"), 14: t("活动物品") };
  const name = (category, id, predicate = row => String(row.id) === String(id)) => (catalog[category] || []).find(predicate)?.name || t("目录编号 {p0}", {p0: id});
  const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  const scalar = value => value === undefined || value === null ? '—' : typeof value === 'boolean' ? (value ? t("已锁定") : t("未锁定")) : value;
  const sections = [];
  function addEntry(section, entry) { if (entry.fields.length) section.entries.push(entry); }
  function diffRows(before, after, key, makeEntry) {
    const oldRows = new Map(before.map(row => [key(row), row]));
    const newRows = new Map(after.map(row => [key(row), row]));
    return [...new Set([...oldRows.keys(), ...newRows.keys()])].map(id => ({ before: oldRows.get(id), after: newRows.get(id) })).filter(row => !equal(row.before, row.after)).map(({ before: oldRow, after: newRow }) => makeEntry(oldRow, newRow));
  }
  for (const change of changes || []) {
    const category = sectionNames[change.label];
    if (!category) throw new Error(t("预览数据类别无法识别，请刷新后重试。"));
    const section = { label: t(change.label), entries: [] };
    if (category === 'resources') {
      for (const [key, label] of Object.entries(resourceLabels)) if (!equal(change.before?.[key], change.after?.[key])) addEntry(section, { name: label, detail: '', fields: [{ label: t("数量"), before: scalar(change.before?.[key]), after: scalar(change.after?.[key]) }] });
    } else if (category === 'items') {
      for (const entry of diffRows(change.before, change.after, row => `${row.type}:${row.id}:${row.eventId ?? ''}`, (before, after) => {
        const row = after || before;
        return { name: name('items', row.id, item => item.type === row.type && item.id === row.id && (item.eventId ?? null) === (row.eventId ?? null)), detail: `${typeLabels[row.type] || t("物品")} · #${row.id}${row.eventId ? t(" · 活动 {p0}", {p0: row.eventId}) : ''}`, fields: [{ label: t("数量"), before: before ? before.qty : t("未持有"), after: after ? after.qty : t("不再持有") }] };
      })) addEntry(section, entry);
    } else if (category === 'cards' || category === 'equipment') {
      for (const entry of diffRows(change.before, change.after, row => String(category === 'cards' ? row.cardId : row.id), (before, after) => {
        const row = after || before; const id = category === 'cards' ? row.cardId : row.equipId;
        const entry = { name: name(category, id), detail: category === 'cards' ? t("兵装 #{p0}", {p0: id}) : t("实例 {p0} · 装备 #{p1}", {p0: row.id, p1: id}), fields: [] };
        if (!before || !after) entry.fields.push({ label: t("持有状态"), before: before ? t("已拥有") : t("未拥有"), after: after ? t("已拥有") : t("未拥有") });
        for (const [key, label] of Object.entries(category === 'cards' ? cardLabels : equipLabels)) {
          if (equal(before?.[key], after?.[key])) continue;
          const display = value => key.endsWith('SkinId') || key === 'skinId' ? (value == null ? '—' : name('skins', value)) : scalar(value);
          entry.fields.push({ label, before: display(before?.[key]), after: display(after?.[key]) });
        }
        return entry;
      })) addEntry(section, entry);
    } else if (category === 'collections') {
      for (const [field, collectionCategory, label] of [['backgroundIds', 'backgrounds', t("背景")], ['titleIds', 'titles', t("称号")], ['skins', 'skins', t("皮肤")]]) {
        const key = row => field === 'skins' ? `${row.cardId}:${row.skinId}` : String(row);
        const oldRows = new Map((change.before[field] || []).map(row => [key(row), row]));
        const newRows = new Map((change.after[field] || []).map(row => [key(row), row]));
        for (const id of new Set([...oldRows.keys(), ...newRows.keys()])) {
          if (oldRows.has(id) === newRows.has(id)) continue;
          const row = newRows.get(id) ?? oldRows.get(id); const definitionId = field === 'skins' ? row.skinId : row;
          addEntry(section, { name: name(collectionCategory, definitionId), detail: `${label} #${definitionId}${field === 'skins' ? ` · ${name('cards', row.cardId)}` : ''}`, fields: [{ label: t("持有状态"), before: oldRows.has(id) ? t("已拥有") : t("未拥有"), after: newRows.has(id) ? t("已拥有") : t("未拥有") }] });
        }
      }
    }
    // Do not imply a readable confirmation if a future response changes an unknown field only.
    if (!section.entries.length && !equal(change.before, change.after)) throw new Error(t("预览包含无法识别的变更，请刷新后重试。"));
    if (section.entries.length) sections.push(section);
  }
  return sections;
}
// PREVIEW_DIFF_END

function readablePreview(changes) {
  const sections = buildPreviewSections(changes, state.catalog);
  if (!sections.length) return `<p class="hint">${t("没有变更。")}</p>`;
  const total = sections.reduce((count, section) => count + section.entries.length, 0);
  return `<p class="preview-total">${t("共 {p0} 项实际变更 · {p1} 类数据", {p0: total, p1: sections.length})}</p>${sections.map(section => {
    const fieldCount = section.entries.reduce((count, entry) => count + entry.fields.length, 0);
    const table = `<div class="table-wrap preview-table"><table><thead><tr><th>${t("条目")}</th><th>${t("修改项")}</th><th>${t("修改前")}</th><th>${t("修改后")}</th></tr></thead><tbody>${section.entries.map(entry => entry.fields.map((field, index) => `<tr>${index === 0 ? `<td rowspan="${entry.fields.length}"><strong>${textNode(entry.name)}</strong>${entry.detail ? `<small class="preview-entry-detail">${textNode(entry.detail)}</small>` : ''}</td>` : ''}<td>${textNode(field.label)}</td><td>${textNode(typeof field.before === 'number' ? fmt(field.before) : field.before)}</td><td class="preview-after">${textNode(typeof field.after === 'number' ? fmt(field.after) : field.after)}</td></tr>`).join('')).join('')}</tbody></table></div>`;
    return `<section class="preview-section"><h3>${textNode(section.label)}<span class="pill">${t("{p1} 项 · {p2} 处变化", {p1: section.entries.length, p2: fieldCount})}</span></h3>${section.entries.length > 8 ? `<details class="preview-batch"><summary>${t("展开 {p0} 项变更明细", {p0: section.entries.length})}</summary>${table}</details>` : table}</section>`;
  }).join('')}`;
}

async function preview(kind, payload, cleanup = null) {
  requireLease();
  const uid = state.uid; const leaseId = state.lease.leaseId; const generation = state.responseGeneration;
  const command = { operationId: operationId(), expectedRevision: state.data.revision, kind, payload };
  const result = await api.preview(uid, leaseId, command);
  if (uid !== state.uid || generation !== state.responseGeneration || !liveLease() || state.lease.leaseId !== leaseId) throw new ApiError('maintenance_required', t("目标或维护状态已变化，请重新预览。"));
  const presentation = readablePreview(result.changes);
  state.pending = { type: 'command', uid, command, cleanup, previewChanges: result.changes };
  $('#review-title').textContent = t("确认存档修改");
  $('#review-body').innerHTML = `<p class="hint">${t("目标：{p0} · UID {p1}", {p0: textNode(state.data.account.name), p1: esc(state.uid)})}</p>${presentation}<p class="hint">${t("提交后请在游戏中重新登录。")}</p>`;
  $('#review-commit').textContent = t("确认写入"); $('#review-dialog').showModal();
  hydrateText($('#review-body'));
}

function showCredentialReview(type, name, password) {
  if (type === 'credentials') requireLease();
  state.pending = { type, uid: state.uid, name, password, operationId: operationId(), expectedRevision: state.data?.revision };
  $('#review-title').textContent = type === 'create' ? t("确认新建账号") : t("确认重新发行引继资料");
  $('#review-body').innerHTML = type === 'create' ? `<p>${t("创建账号 ")}<strong>${textNode(name)}</strong>${t("。新号特典会在完成教程后首次进入主页时发放。")}</p>` : `<p>${t("将为 ")}<strong>${textNode(state.data.account.name)}</strong>${t("（UID {p1}）重新发行引继资料。", {p1: esc(state.uid)})}</p>`;
  const note = document.createElement('p'); note.className = 'warning'; note.textContent = t("请保存成功后显示的引继资料。"); $('#review-body').append(note);
  hydrateText($('#review-body'));
  $('#review-commit').textContent = type === 'create' ? t("确认创建") : t("确认发行"); $('#review-dialog').showModal();
}

function showCredentials(credentials, uid = state.uid) {
  const record = credentialRecord({ uid, takeoverId: credentials.takeoverId, password: credentials.password });
  if (!record) throw new ApiError('invalid_credentials', t("请重新发行引继资料。"));
  state.unreadCredentials = record;
  nativeCredentials('retain', record);
  const result = $('#credentials-result'); result.replaceChildren();
  for (const [field, label, value] of [['id', t("引继 ID"), record.takeoverId], ['password', t("密码"), record.password]]) {
    const term = document.createElement('dt'); term.textContent = label;
    const detail = document.createElement('dd');
    const input = document.createElement('input'); input.type = 'text'; input.id = `credential-value-${field}`;
    input.value = value; input.readOnly = true; input.autocomplete = 'off'; input.spellcheck = false;
    input.setAttribute('autocapitalize', 'off'); input.setAttribute('aria-label', label);
    detail.append(input); result.append(term, detail);
  }
  if (!$('#credentials-dialog').open) $('#credentials-dialog').showModal();
}

async function commitPending() {
  const pending = state.pending; if (!pending) return;
  if (pending.type !== 'create') { requireLease(); if (pending.uid !== state.uid) throw new ApiError('stale_revision', t("目标账号已经变化。")); }
  let result;
  if (pending.type === 'command') result = await api.commit(pending.uid, state.lease.leaseId, pending.command);
  else if (pending.type === 'create') result = await api.create({ operationId: pending.operationId, name: pending.name, password: pending.password });
  else result = await api.credentials(pending.uid, state.lease.leaseId, { operationId: pending.operationId, expectedRevision: pending.expectedRevision, password: pending.password });
  pending.cleanup?.();
  if (pending.type === 'create') $('#create-form')?.reset();
  else if (pending.type === 'credentials') $('#credentials-form')?.reset();
  abandonReview();
  if (result.credentials) showCredentials(result.credentials, result.uid || pending.uid);
  // The mutation is already durable. Refresh failure must not turn success into a retry invitation.
  notify(result.replayed ? t("操作已完成。") : t("已保存，请在游戏中重新登录。"));
  try { await refreshData(); } catch (error) { notify(t("已保存；刷新失败，请手动刷新。"), true); }
}

function openGrowth(category, id) {
  requireLease();
  const owned = category === 'cards' ? state.data.cards.find(row => row.cardId === Number(id)) : state.data.equipment.find(row => row.id === id);
  const definition = state.catalog[category].find(row => row.id === (category === 'cards' ? owned.cardId : owned.equipId));
  if (!definition) throw new ApiError('catalog_unavailable', t("此条目的成长目录不可用。"));
  const limits = growthLimits(definition, owned, category);
  state.pending = { type: 'growth-editor', category, id, owned, definition };
  $('#review-title').textContent = t("{p0} · 成长目标", {p0: names(category, definition.id)});
  $('#review-body').innerHTML = `<p class="hint">${category === 'cards' ? t("等级和技能上限随觉醒变化。") : t("等级上限随突破变化；保留原有词条。")}</p><form id="growth-form"><div class="grow-editor">${Object.entries(limits).map(([key, [min, max]]) => `<div class="field"><label for="growth-${key}">${growthNames[key]}</label><input id="growth-${key}" name="${key}" type="number" step="1" min="${min}" max="${max}" value="${owned[key]}" required><span class="field-note" data-growth-note="${key}">${t("允许 {p8}–{p9}", {p8: min, p9: max})}</span></div>`).join('')}${category === 'equipment' ? `<label><input type="checkbox" name="locked" ${owned.locked ? 'checked' : ''}>${t(" 锁定装备")}</label>` : ''}</div></form>`;
  $('#review-commit').textContent = t("预览成长调整"); $('#review-dialog').showModal();
}

async function previewGrowth() {
  const pending = state.pending; const form = $('#growth-form');
  if (!form.reportValidity()) return;
  const growth = Object.fromEntries([...new FormData(form)].filter(([key]) => key !== 'locked').map(([key, value]) => [key, Number(value)]));
  if (pending.category === 'equipment') growth.locked = form.elements.locked.checked;
  const category = pending.category; const id = pending.id;
  abandonReview();
  await preview(category === 'cards' ? 'cards.growth' : 'equipment.growth', category === 'cards' ? { cards: [{ cardId: Number(id), ...growth }] } : { equipment: [{ id, ...growth }] });
}

function openGrant(id) {
  requireLease(); state.pending = { type: 'grant-editor', equipId: Number(id) };
  const remaining = state.catalog.limits.maxEquipment - state.data.equipment.length;
  const maximum = Math.min(remaining, state.catalog.limits.maxItemsPerCommand);
  $('#review-title').textContent = t("添加 {p0}", {p0: names('equipment', id)});
  $('#review-body').innerHTML = `<form id="grant-form"><div class="field"><label for="grant-quantity">${t("添加数量")}</label><input id="grant-quantity" name="quantity" type="number" min="1" max="${maximum}" value="1" required><span class="field-note">${t("当前库存剩余容量 {p1} 件，本次最多添加 {p2} 件", {p1: remaining, p2: maximum})}</span></div><label class="field-spaced"><input name="locked" type="checkbox">${t(" 添加后锁定")}</label></form>`;
  $('#review-commit').textContent = t("预览添加装备"); $('#review-dialog').showModal();
}

async function download(kind) {
  if (window.__BRSF_NATIVE_DOWNLOADS__ === true) {
    const path = kind === 'backup' ? '/management/v1/backup' : `/management/v1/accounts/${encodeURIComponent(state.uid)}/export`;
    window.location.assign(path);
    notify(t("请选择文件保存位置。"));
    return;
  }
  const result = kind === 'backup' ? await api.backup() : await api.export(state.uid);
  const url = URL.createObjectURL(result.blob); const link = document.createElement('a');
  link.href = url; link.download = kind === 'backup' ? `brsf-backup-${new Date().toISOString().slice(0, 10)}.sqlite3` : `account-${state.uid}.json`;
  document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  notify(kind === 'backup' ? t("已发起整服备份下载。") : t("已发起账号数据下载。"));
}

async function action(name, button) {
  if (name === 'begin') { state.lease = await api.begin(state.uid); state.leaseWasExpired = false; state.data = await api.account(state.uid); render(); notify(t("已进入维护。")); }
  else if (name === 'renew') { requireLease(); state.lease = await api.renew(state.uid, state.lease.leaseId); renderAccountStrip(); }
  else if (name === 'release') { requireLease(); await api.release(state.uid, state.lease.leaseId); state.lease = null; state.leaseWasExpired = false; abandonReview(); render(); notify(t("已释放维护。")); }
  else if (name === 'expert-period-refresh') await refreshExpertPeriod();
  else if (name === 'expert-period-apply') await applyExpertPeriod();
  else if (name === 'backup' || name === 'export') await download(name);
  else if (name === 'stamina-full') { putDraft('wallet:stamina', state.data.resources.staminaMax, state.data.resources.stamina); render(); }
  else if (name === 'wallet-preview') {
    const payload = {}; const limits = state.catalog.limits;
    const submitted = new Map([...state.drafts].filter(([key]) => key.startsWith('wallet:')));
    const originals = new Map([...submitted].map(([key]) => [key, state.data.resources[key.slice(7)]]));
    for (const [key, value] of submitted) { const currency = key.slice(7); payload[currency] = numeric(value, 0, limits[`max${currency[0].toUpperCase()}${currency.slice(1)}`], currencyNames[currency]); }
    if (!Object.keys(payload).length) throw new ApiError('invalid_request', t("尚未修改钱包或体力。"));
    await preview('wallet.set', payload, () => clearSubmittedDrafts(submitted, originals));
  } else if (name === 'items-preview') {
    const items = [];
    const submitted = new Map([...state.drafts].filter(([key]) => key.startsWith('item:')));
    const originals = new Map();
    for (const [key, value] of submitted) {
      const [, type, id, eventId] = key.split(':'); const definition = state.catalog.items.find(row => row.type === Number(type) && row.id === Number(id) && String(row.eventId ?? '') === eventId);
      originals.set(key, state.data.items.find(row => row.type === Number(type) && row.id === Number(id) && String(row.eventId ?? '') === eventId)?.qty || 0);
      items.push({ type: Number(type), id: Number(id), qty: numeric(value, 0, definition.maxQty, definition.name), ...(eventId ? { eventId: Number(eventId) } : {}) });
    }
    if (!items.length) throw new ApiError('invalid_request', t("尚未修改道具或材料数量。"));
    if (items.length > state.catalog.limits.maxItemsPerCommand) throw new ApiError('invalid_request', t("每次最多调整 {p0} 项。", {p0: state.catalog.limits.maxItemsPerCommand}));
    await preview('items.set', { items }, () => clearSubmittedDrafts(submitted, originals));
  } else if (name === 'cards-ensure') {
    const ids = selectedIds('cards:catalog');
    await preview('cards.ensure', { cardIds: ids }, () => clearSubmittedSelections('cards:catalog', ids));
  } else if (name === 'cards-max' || name === 'cards-max-all') {
    const ids = name.endsWith('-all') ? null : selectedIds('cards:owned');
    const submitted = ids || [...selectedSet('cards:owned')];
    await preview('cards.max', { cardIds: ids }, () => clearSubmittedSelections('cards:owned', submitted));
  } else if (name === 'equipment-max' || name === 'equipment-max-all') {
    const ids = name.endsWith('-all') ? null : selectedIds('equipment:owned', false);
    const submitted = ids || [...selectedSet('equipment:owned')];
    await preview('equipment.max', { equipmentIds: ids }, () => clearSubmittedSelections('equipment:owned', submitted));
  } else if (name === 'equipment-lock') {
    const ids = selectedIds('equipment:owned', false);
    await preview('equipment.lock', { equipmentIds: ids, locked: button.dataset.locked === 'true' }, () => clearSubmittedSelections('equipment:owned', ids));
  }
  else if (name === 'collection-grant') {
    const category = state.modes.collection; const ids = selectedIds(`collection:${category}`);
    const payload = { skins: [], backgroundIds: [], titleIds: [] };
    if (category === 'skins') payload.skins = ids.map(id => { const row = state.catalog.skins.find(item => item.id === id); return { cardId: row.cardId, skinId: row.id }; });
    else payload[category === 'backgrounds' ? 'backgroundIds' : 'titleIds'] = ids;
    await preview('collection.grant', payload, () => clearSubmittedSelections(`collection:${category}`, ids));
  }
}

document.addEventListener('click', event => {
  const button = event.target.closest('button'); if (!button || button.disabled) return;
  if (button.dataset.page) { state.page = button.dataset.page; render(); if (state.page === 'settings') void run(refreshExpertPeriod); }
  else if (button.dataset.modePage) { state.modes[button.dataset.modePage] = button.dataset.mode; state.pages[button.dataset.modePage] = 1; render(); }
  else if (button.dataset.pagination) { const key = button.dataset.pagination; state.pages[key] += Number(button.dataset.offset); render(); }
  else if (button.dataset.selectAccount) {
    const selection = button.dataset.accountIdentity ? window.getSelection?.() : null;
    if (selection && String(selection).trim() && selection.containsNode(button, true)) return;
    run(() => selectAccount(button.dataset.selectAccount));
  }
  else if (button.dataset.action) run(() => action(button.dataset.action, button));
  else if (button.dataset.cardEdit) run(() => openGrowth('cards', button.dataset.cardEdit));
  else if (button.dataset.equipmentEdit) run(() => openGrowth('equipment', button.dataset.equipmentEdit));
  else if (button.dataset.equipmentGrant) run(() => openGrant(button.dataset.equipmentGrant));
  else if (button.dataset.copyCredentials) void copyCredentials(button.dataset.copyCredentials);
  else if (button.dataset.generatePassword) { const input = document.getElementById(button.dataset.generatePassword); input.value = randomPassword(); notify(t("已生成12位密码。")); }
  else if (button.hasAttribute('data-close-dialog')) abandonReview();
});

document.addEventListener('input', event => {
  const input = event.target;
  if (input.dataset.draft) putDraft(input.dataset.draft, input.value, input.dataset.original);
  if (input.dataset.search) {
    const key = input.dataset.search; const position = input.selectionStart;
    state.search[key] = input.value; state.pages[key] = 1; render();
    const replacement = document.getElementById(input.id); replacement?.focus(); replacement?.setSelectionRange(position, position);
  }
  if (input.id === 'growth-awakening' || input.id === 'growth-breakthrough') {
    const pending = state.pending;
    const current = { awakening: Number($('#growth-awakening')?.value), breakthrough: Number($('#growth-breakthrough')?.value) };
    for (const [key, [min, max]] of Object.entries(growthLimits(pending.definition, current, pending.category))) {
      const field = $(`#growth-${key}`); if (field) { field.min = min; field.max = max; $(`[data-growth-note="${key}"]`).textContent = t("允许 {p0}–{p1}", {p0: min, p1: max}); }
    }
  }
});

document.addEventListener('change', event => {
  const input = event.target;
  if (input.id === 'material-category') { state.materialCategory = input.value; state.pages.items = 1; render(); }
  if (input.id === 'expert-period-select') { state.expertSelection = input.value; syncSettingsControls(); }
  if (input.dataset.selection) { const selection = selectedSet(input.dataset.selection); input.checked ? selection.add(input.value) : selection.delete(input.value); render(); }
  if (input.dataset.selectVisible) { const key = input.dataset.selectVisible; const selection = selectedSet(key); document.querySelectorAll(`[data-selection="${key}"]:not(:disabled)`).forEach(box => { input.checked ? selection.add(box.value) : selection.delete(box.value); }); render(); }
});

document.addEventListener('error', event => {
  const image = event.target;
  if (image.tagName !== 'IMG' || !image.hasAttribute('data-catalog-thumb')) return;
  image.hidden = true;
  if (image.nextElementSibling) image.nextElementSibling.hidden = false;
}, true);

$('#login-form').addEventListener('submit', event => { event.preventDefault(); const key = $('#owner-key').value; $('#owner-key').value = ''; run(async () => { await api.login(key); await loadWorkbench(); }); });
document.addEventListener('submit', event => {
  if (event.target.id === 'create-form') { event.preventDefault(); const form = event.target; if (!form.reportValidity()) return; const name = form.elements.name.value.trim(); const password = form.elements.password.value; form.elements.password.value = ''; run(() => showCredentialReview('create', name, password)); }
  if (event.target.id === 'credentials-form') { event.preventDefault(); const form = event.target; if (!form.reportValidity()) return; const password = form.elements.password.value; form.elements.password.value = ''; run(() => showCredentialReview('credentials', '', password)); }
});
$('#review-commit').addEventListener('click', () => run(async () => {
  if (state.pending?.type === 'growth-editor') await previewGrowth();
  else if (state.pending?.type === 'grant-editor') { const form = $('#grant-form'); if (!form.reportValidity()) return; const payload = { equipId: state.pending.equipId, quantity: Number(form.elements.quantity.value), locked: form.elements.locked.checked }; abandonReview(); await preview('equipment.grant', payload); }
  else await commitPending();
}));
$('#review-dialog').addEventListener('cancel', () => abandonReview());
$('#credentials-dialog').addEventListener('cancel', event => { event.preventDefault(); dismissCredentials(); });
$('#credentials-dismiss').addEventListener('click', dismissCredentials);
$('#logout').addEventListener('click', () => run(async () => { if (state.drafts.size && !confirm(t("退出会丢弃未保存的修改，继续退出？"))) return; try { await api.logout(); } catch { notify(t("退出请求失败，请检查服务连接。"), true); } finally { dismissCredentials(); showLogin(); } }));
$('#refresh').addEventListener('click', () => run(async () => { abandonReview(); if (state.page === 'settings') await refreshExpertPeriod(); else await refreshData(); notify(state.drafts.size ? t("已刷新，草稿已保留。") : t("已刷新。")); }));
window.addEventListener('beforeunload', event => { if (state.drafts.size || liveLease() || state.unreadCredentials) { event.preventDefault(); event.returnValue = ''; } });
window.addEventListener('brsf-native-credentials-ready', restoreCredentials);
window.addEventListener('brsf-management-resume', () => { void resumeManagement(); });
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') void resumeManagement(); });
setInterval(() => {
  if (!state.uid) return;
  if (state.lease && !liveLease()) { state.lease = null; state.leaseWasExpired = true; abandonReview(); notify(t("维护已到期，请重新进入。"), true); }
  renderAccountStrip();
}, 1000);

function applyStaticLanguage() {
  document.documentElement.lang = getLocale();
  document.title = t('BRS FRAGMENT · 存档工作台');
  document.querySelectorAll('[data-i18n]').forEach(node => { node.textContent = t(node.dataset.i18n); });
  for (const attribute of ['aria-label', 'placeholder']) document.querySelectorAll(`[data-i18n-${attribute}]`).forEach(node => { node.setAttribute(attribute, t(node.getAttribute(`data-i18n-${attribute}`))); });
  $('#language-select').value = getPreference();
}
function snapshotFields() {
  return [...document.querySelectorAll('input, select, textarea')].filter(node => node.id !== 'language-select').map(node => ({ id:node.id, form:node.form?.id, name:node.name, value:node.value, checked:node.checked, start:node.selectionStart, end:node.selectionEnd }));
}
function restoreFields(fields) {
  for (const saved of fields) {
    const node = saved.id ? document.getElementById(saved.id) : saved.form ? document.getElementById(saved.form)?.elements.namedItem(saved.name) : null;
    if (!node) continue;
    node.value = saved.value; if (typeof saved.checked === 'boolean') node.checked = saved.checked;
    try { if (saved.start != null) node.setSelectionRange(saved.start, saved.end); } catch {}
  }
}
function refreshLocalizedDialogs() {
  const pending = state.pending;
  if (pending && $('#review-dialog').open) {
    if (pending.type === 'command') {
      $('#review-title').textContent = t('确认存档修改');
      $('#review-body').innerHTML = `<p class="hint">${t('目标：{p0} · UID {p1}',{p0:textNode(state.data.account.name),p1:esc(state.uid)})}</p>${readablePreview(pending.previewChanges)}<p class="hint">${t('提交后请在游戏中重新登录。')}</p>`;
      $('#review-commit').textContent = t('确认写入'); hydrateText($('#review-body'));
    } else if (pending.type === 'create' || pending.type === 'credentials') showCredentialReview(pending.type, pending.name, pending.password);
    else if (pending.type === 'growth-editor') openGrowth(pending.category, pending.id);
    else if (pending.type === 'grant-editor') openGrant(pending.equipId);
    state.pending = pending;
  }
  if (state.unreadCredentials && $('#credentials-dialog').open) {
    const terms = $('#credentials-result').querySelectorAll('dt');
    if (terms[0]) terms[0].textContent = t('引继 ID');
    if (terms[1]) terms[1].textContent = t('密码');
    $('#credential-value-id')?.setAttribute('aria-label', t('引继 ID'));
    $('#credential-value-password')?.setAttribute('aria-label', t('密码'));
  }
}
function refreshLanguageUi() {
  const fields = snapshotFields(), activeId = document.activeElement?.id;
  applyStaticLanguage();
  if (state.catalog) state.catalog = localizeCatalog(state.rawCatalog || state.catalog);
  if (state.authenticated && state.catalog) render();
  refreshLocalizedDialogs(); restoreFields(fields);
  if (activeId) document.getElementById(activeId)?.focus();
  if (!$('#notice').hidden) $('#notice').textContent = retranslate($('#notice').textContent);
  if (state.serverSchema != null) $('#server-status').textContent = t('本机服主 · schema {p0}',{p0:state.serverSchema});
}
onLanguageChange(refreshLanguageUi);
$('#language-select').addEventListener('change', event => setLanguagePreference(event.target.value));
applyStaticLanguage();

run(async () => { const session = await api.session(); if (session.authenticated) await loadWorkbench(); else showLogin(); });
